/**
 * Navbar component for the Verity SPA.
 * Renders logo image, navigation links, and mobile hamburger menu.
 */

/**
 * Navigation link definitions.
 * @type {Array<{label: string, href: string, matchPattern: RegExp}>}
 */
const NAV_LINKS = [
  { label: 'Conditions', href: '#/gap-index', matchPattern: /^#?\/(gap-index|conditions\/)/ },
  { label: 'Gap Index', href: '#/gap-index', matchPattern: /^#?\/gap-index/ },
  { label: 'About', href: '#/about', matchPattern: /^#?\/about/ },
];

/**
 * Render the navbar into the given container element.
 * @param {HTMLElement} container — the <nav> element to populate
 */
export function renderNavbar(container) {
  container.setAttribute('aria-label', 'Main navigation');
  container.className = 'navbar';

  // ── Inner wrapper ──
  const inner = document.createElement('div');
  inner.className = 'navbar__inner';

  // ── Logo ──
  const logoLink = document.createElement('a');
  logoLink.href = '#/';
  logoLink.className = 'navbar__logo';
  logoLink.setAttribute('aria-label', 'Verity — Home');

  const logoImg = document.createElement('img');
  logoImg.src = 'data:image/png;base64,';
  logoImg.alt = 'Verity';
  logoImg.className = 'navbar__logo-img';
  logoImg.style.height = '38px';
  logoImg.style.width = 'auto';
  logoLink.appendChild(logoImg);

  // ── Desktop nav links ──
  const navList = document.createElement('ul');
  navList.className = 'navbar__links';
  navList.setAttribute('role', 'list');

  NAV_LINKS.forEach((link) => {
    const li = document.createElement('li');
    const a = document.createElement('a');
    a.href = link.href;
    a.className = 'navbar__link';
    a.textContent = link.label;
    a.dataset.matchPattern = link.matchPattern.source;
    li.appendChild(a);
    navList.appendChild(li);
  });

  // ── Mobile hamburger button ──
  const hamburger = document.createElement('button');
  hamburger.className = 'navbar__hamburger';
  hamburger.setAttribute('aria-label', 'Open navigation menu');
  hamburger.setAttribute('aria-expanded', 'false');
  hamburger.setAttribute('aria-controls', 'mobile-menu-overlay');
  hamburger.type = 'button';

  // Three-bar icon
  for (let i = 0; i < 3; i++) {
    const bar = document.createElement('span');
    bar.className = 'navbar__hamburger-bar';
    bar.setAttribute('aria-hidden', 'true');
    hamburger.appendChild(bar);
  }

  inner.appendChild(logoLink);
  inner.appendChild(navList);
  inner.appendChild(hamburger);
  container.appendChild(inner);

  // ── Mobile overlay ──
  const overlay = document.createElement('div');
  overlay.id = 'mobile-menu-overlay';
  overlay.className = 'navbar__overlay';
  overlay.setAttribute('role', 'dialog');
  overlay.setAttribute('aria-modal', 'true');
  overlay.setAttribute('aria-label', 'Mobile navigation menu');
  overlay.hidden = true;

  const overlayInner = document.createElement('div');
  overlayInner.className = 'navbar__overlay-inner';

  // Close button
  const closeBtn = document.createElement('button');
  closeBtn.className = 'navbar__overlay-close';
  closeBtn.setAttribute('aria-label', 'Close navigation menu');
  closeBtn.type = 'button';
  closeBtn.textContent = '×';

  // Mobile nav links
  const mobileNavList = document.createElement('ul');
  mobileNavList.className = 'navbar__overlay-links';
  mobileNavList.setAttribute('role', 'list');

  // Add Home link in mobile menu
  const homeLi = document.createElement('li');
  const homeA = document.createElement('a');
  homeA.href = '#/';
  homeA.className = 'navbar__overlay-link';
  homeA.textContent = 'Home';
  homeLi.appendChild(homeA);
  mobileNavList.appendChild(homeLi);

  NAV_LINKS.forEach((link) => {
    const li = document.createElement('li');
    const a = document.createElement('a');
    a.href = link.href;
    a.className = 'navbar__overlay-link';
    a.textContent = link.label;
    li.appendChild(a);
    mobileNavList.appendChild(li);
  });

  overlayInner.appendChild(closeBtn);
  overlayInner.appendChild(mobileNavList);
  overlay.appendChild(overlayInner);
  container.appendChild(overlay);

  // ── Event handlers ──

  // Toggle overlay
  hamburger.addEventListener('click', () => {
    const isOpen = !overlay.hidden;
    if (isOpen) {
      closeOverlay();
    } else {
      openOverlay();
    }
  });

  closeBtn.addEventListener('click', closeOverlay);

  // Close on overlay background click
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) {
      closeOverlay();
    }
  });

  // Close on Escape
  overlay.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      closeOverlay();
    }
  });

  // Close overlay and navigate when mobile links are clicked
  mobileNavList.addEventListener('click', (e) => {
    const link = e.target.closest('a');
    if (link) {
      closeOverlay();
    }
  });

  function openOverlay() {
    overlay.hidden = false;
    hamburger.setAttribute('aria-expanded', 'true');
    document.body.style.overflow = 'hidden';
    closeBtn.focus();
  }

  function closeOverlay() {
    overlay.hidden = true;
    hamburger.setAttribute('aria-expanded', 'false');
    document.body.style.overflow = '';
    hamburger.focus();
  }

  // ── Active link tracking ──
  function updateActiveLinks() {
    const hash = window.location.hash || '#/';

    // Desktop links
    navList.querySelectorAll('.navbar__link').forEach((a) => {
      const pattern = new RegExp(a.dataset.matchPattern);
      if (pattern.test(hash)) {
        a.classList.add('active');
        a.setAttribute('aria-current', 'page');
      } else {
        a.classList.remove('active');
        a.removeAttribute('aria-current');
      }
    });

    // Mobile links
    mobileNavList.querySelectorAll('.navbar__overlay-link').forEach((a) => {
      const linkHash = a.getAttribute('href');
      if (hash === linkHash || (linkHash !== '#/' && hash.startsWith(linkHash.replace('#', '#')))) {
        a.classList.add('active');
      } else {
        a.classList.remove('active');
      }
    });
  }

  updateActiveLinks();
  window.addEventListener('hashchange', updateActiveLinks);
}
